]);
export const SPAWN = Object.freeze({ x: 64 * UNIT, y: 296 * UNIT });
export const PLATFORM = Object.freeze({
  x: 480 * UNIT,
  y: 256 * UNIT,
  width: 64 * UNIT,
  height: 12 * UNIT,
  travel: 48 * UNIT,
  period: 192,
});

